//
// Risk and performance statistics from a series of returns: historical VaR and expected
// shortfall, EWMA (RiskMetrics) volatility, drawdown, Sharpe ratio, rolling means.
#pragma once

#include <cmath>
#include <stdexcept>
#include "qtrans_arrays.hpp"  // Eigen, plus NumPy semantics

namespace risk {

// Declarations (so functions can call each other in any order).
double historical_var(const qt::Vec& returns, double alpha = 0.99);
double expected_shortfall(const qt::Vec& returns, double alpha = 0.99);
qt::Vec ewma_vol(const qt::Vec& returns, double lam = 0.94);
double max_drawdown(const qt::Vec& prices);
double sharpe_ratio(const qt::Vec& returns, double rf = 0.0, long long periods = 252);
qt::Vec wealth_curve(const qt::Vec& returns, double start = 1.0);
qt::Vec rolling_mean(const qt::Vec& x, long long window);
double downside_deviation(const qt::Vec& returns, double target = 0.0);

/// Loss not exceeded with probability alpha, from the empirical distribution.
inline double historical_var(const qt::Vec& returns, double alpha) {
    return -qt::quantile(returns, 1 - alpha);
}

/// Average loss over the returns at or below the (1 - alpha) quantile.
inline double expected_shortfall(const qt::Vec& returns, double alpha) {
    double q = qt::quantile(returns, 1 - alpha);
    qt::Vec tail = qt::where(returns <= q, returns, 0.0);
    return -qt::sum(tail) / static_cast<double>((returns <= q).count());
}

/// RiskMetrics volatility: var_t = lam * var_{t-1} + (1 - lam) * r_{t-1}^2.
inline qt::Vec ewma_vol(const qt::Vec& returns, double lam) {
    qt::Vec var = qt::zeros(returns.size());
    if (returns.size() == 0) {
        return var;
    }
    var(0) = std::pow(returns(0), 2);
    const long long t_end = returns.size();
    for (long long t = 1; t < t_end; ++t) {
        var(t) = lam * var(t - 1) + (1 - lam) * std::pow(returns(t - 1), 2);
    }
    return var.sqrt();
}

/// Largest fall from a running peak, as a fraction of that peak.
inline double max_drawdown(const qt::Vec& prices) {
    double peak = prices(0);
    double worst = 0.0;
    for (double p : prices) {
        if (p > peak) {
            peak = p;
        }
        double dd = (peak - p) / peak;
        if (dd > worst) {
            worst = dd;
        }
    }
    return worst;
}

inline double sharpe_ratio(const qt::Vec& returns, double rf, long long periods) {
    qt::Vec excess = returns - rf / static_cast<double>(periods);
    return qt::mean(excess) / qt::std_(excess, 1) * std::sqrt(periods);
}

inline qt::Vec wealth_curve(const qt::Vec& returns, double start) {
    return start * qt::cumprod(1.0 + returns);
}

/// Mean of every full window, from cumulative sums.
inline qt::Vec rolling_mean(const qt::Vec& x, long long window) {
    if (window < 1 || window > x.size()) {
        throw std::invalid_argument("window must be between 1 and len(x)");
    }
    qt::Vec c = qt::cumsum(x);
    qt::Vec out = qt::zeros(x.size() - window + 1);
    out(0) = c(qt::idx(window - 1, c.size())) / static_cast<double>(window);
    qt::slice(out, 1, qt::none) = (qt::slice(c, window, qt::none) - qt::slice(c, qt::none, -window)) / static_cast<double>(window);
    return out;
}

inline double downside_deviation(const qt::Vec& returns, double target) {
    qt::Vec shortfall = qt::minimum(returns - target, 0.0);
    return std::sqrt(qt::mean(shortfall.square()));
}

}  // namespace risk
